const rows = $('Collect Blog Topics').first().json.topics || [];
const published = new Set($('Fetch Blog Index').all().map(item => item.json?.slug).filter(Boolean));
const now = Date.now();
const selected = rows.find(row => {
  const slug = String(row.Slug || '').trim();
  const status = String(row.Status || '').trim().toLowerCase();
  const due = String(row['Publish After'] || '').trim();
  return ['ready', 'queued'].includes(status) && /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)
    && !published.has(slug) && (!due || (Number.isFinite(Date.parse(due)) && Date.parse(due) <= now));
});
if (!selected) return [];
const title = String(selected['Blog Title'] || '').trim();
const type = String(selected.Type || 'Guide').trim();
if (!title || !['Guide', 'Comparison', 'Listicle'].includes(type)) return [];
const safeUrl = (value, fallback) => {
  const url = String(value || '').trim();
  return /^https:\/\/[^\s<>\"']+$/.test(url) ? url : fallback;
};
const escape = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const coverImageUrl = safeUrl(selected['Cover Image URL'], '');
const inlineImageUrl = safeUrl(selected['Inline Image URL'], '');
if (!coverImageUrl || !inlineImageUrl || coverImageUrl === inlineImageUrl) throw new Error('Two distinct HTTPS image URLs are required in the selected Google Sheet row');
const inlineImageHtml = `<figure><img src="${escape(inlineImageUrl)}" alt="${escape('Visual guide: ' + title)}" loading="lazy"><figcaption>${escape('Conceptual illustration of the workflow described in this guide.')}</figcaption></figure>`;
return [{json: {...selected, slug: String(selected.Slug).trim(), type, 'Blog Title ': title,
  'Key Points': String(selected['Key Points'] || '').trim(), Author: String(selected['Author Name'] || 'Taskwise').trim(),
  coverImageUrl, inlineImageUrl, inlineImageHtml}}];

