parameters.jsCode:
const BASE = 'https://www.taskwise.ai';
const blogs=$input.all().map(it=>it.json||{}).filter(j=>j.slug && j.status==='published').map(j=>({url:BASE+'/blog/'+j.slug,type:'blog',title:j.title||j.slug,summary:j.shortsummary||'',tags:j.tags||'',primary_keyword:j.targetkeyword||j.title||j.slug}));
const pages=[{url:BASE+'/',type:'product',title:'TaskwiseAI',summary:'Turn meeting memory into reviewed action.',tags:'meetings, tasks, execution'},{url:BASE+'/features',type:'product',title:'Taskwise features',summary:'Capture, understand, review and execute meeting follow-ups.',tags:'meeting memory, task review, planning'},{url:BASE+'/integrations',type:'product',title:'Taskwise integrations',summary:'Meeting capture and connected follow-up tools.',tags:'Fathom, Slack, calendar, Trello'},{url:BASE+'/mcp',type:'product',title:'Taskwise MCP',summary:'Scoped agent access to workspace meeting memory and tasks.',tags:'MCP, workspace, agent'}];
return [{json:{candidates:[...blogs,...pages],candidateCount:blogs.length+pages.length}}];

const seo = {...($json.output || {}), slug: $('Select Taskwise Topic').first().json.slug};
const all = $('Build Candidate List').first().json.candidates || [];
const MAX_CANDIDATES = 40;

const STOP = new Set(['the','and','for','with','your','you','how','what','why','are','from','that','this','into','best','guide','using','can','n8n','ai']);
const words = (s) => String(s || '').toLowerCase().match(/[a-z0-9]{3,}/g) || [];
const bag = new Set(words(seo.title + ' ' + seo.tags + ' ' + seo.category + ' ' + seo.shortsummary).filter(w => !STOP.has(w)));

const selfUrl = 'https://www.taskwise.ai/blog/' + (seo.slug || '');

const scored = all
  .filter(c => c.url !== selfUrl)
  .map(c => {
    const cw = new Set(words(c.title + ' ' + c.tags + ' ' + c.summary + ' ' + c.primary_keyword).filter(w => !STOP.has(w)));
    let score = 0;
    for (const w of cw) if (bag.has(w)) score++;
    return { c, score };
  });

// sve ne-blog stranice uvek ostaju, blogovi se seku na MAX_CANDIDATES
const pages = scored.filter(x => x.c.type !== 'blog').map(x => x.c);
const blogs = scored.filter(x => x.c.type === 'blog' && x.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, MAX_CANDIDATES)
  .map(x => x.c);

const candidates = [...blogs, ...pages];

return {
  json: {
    slug: seo.slug || '',
    title: seo.title || '',
    category: seo.category || '',
    tags: seo.tags || '',
    shortsummary: seo.shortsummary || '',
    content: seo.content || '',
    candidate_urls: JSON.stringify(candidates, null, 1),
    candidateCount: candidates.length
  }
};

// Verifikuje ono sto je model vratio. Ako provera padne, linkovi se primenjuju
// deterministicki na originalni HTML. Clanak ne moze da bude ostecen.

const seo = {...$('SEO Agent').item.json.output, slug: $('Select Taskwise Topic').first().json.slug};
const original = String($('Prep Interlink Input').item.json.content || '');
const modelOut = $json.output || {};
const modelContent = String(modelOut.content || '');
const linksAdded = Array.isArray(modelOut.links_added) ? modelOut.links_added : [];
const skippedReason = modelOut.links_skipped_reason || '';

const cands = $('Build Candidate List').first().json.candidates || [];
const whitelist = new Set(cands.map(c => String(c.url).replace(/\/+$/, '')));
const selfUrl = ('https://www.taskwise.ai/blog/' + (seo.slug || '')).replace(/\/+$/, '');

const count = (s, re) => (s.match(re) || []).length;
const hrefs = (s) => (s.match(/<a\b[^>]*href="([^"]+)"/gi) || [])
  .map(m => (m.match(/href="([^"]+)"/i) || [])[1])
  .map(u => String(u).replace(/\/+$/, ''));

const originalHrefs = new Set(hrefs(original));
const failures = [];

if (!modelContent) failures.push('model nije vratio content');

if (modelContent) {
  for (const [label, re] of [['h2', /<h2\b/gi], ['h3', /<h3\b/gi], ['li', /<li\b/gi], ['tr', /<tr\b/gi], ['table', /<table\b/gi]]) {
    if (count(modelContent, re) !== count(original, re)) failures.push('broj ' + label + ' se ne poklapa');
  }
  if (modelContent.length < original.length) failures.push('content je kraci od originala');
  if (/<a\b[^>]*>(?:(?!<\/a>)[\s\S])*?<a\b/i.test(modelContent)) failures.push('ugnjezden <a> tag');

  const newHrefs = hrefs(modelContent).filter(u => !originalHrefs.has(u));
  const seenH = new Set();
  for (const u of newHrefs) {
    if (!whitelist.has(u)) failures.push('URL van liste kandidata: ' + u);
    if (u === selfUrl) failures.push('self link: ' + u);
    if (seenH.has(u)) failures.push('duplikat URL: ' + u);
    seenH.add(u);
  }
  if (newHrefs.length > 7) failures.push('vise od 7 novih linkova');

  const firstH2 = modelContent.search(/<h2\b/i);
  if (firstH2 > 0) {
    const introNew = hrefs(modelContent.slice(0, firstH2)).filter(u => !originalHrefs.has(u));
    if (introNew.length > 2) failures.push('vise od 2 linka u introu');
  }
}

if (failures.length === 0) {
  return {
    json: {
      output: { ...seo, content: modelContent },
      interlinkMode: 'model',
      interlinks: linksAdded,
      interlinkCount: linksAdded.length,
      interlinkSkippedReason: skippedReason,
      interlinkFailures: []
    }
  };
}

// ---------- FALLBACK: deterministicko ubacivanje na osnovu links_added ----------
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const BLOCKED = /^<\/?(a|h1|h2|h3|h4|h5|h6|code|pre|script|style)\b/i;

function insertLink(source, anchor, url) {
  if (!anchor || anchor.length < 3) return { html: source, ok: false, matched: null };
  const re = new RegExp('(?<![\\w-])' + escapeRe(anchor) + '(?![\\w-])');
  const parts = source.split(/(<[^>]+>)/g);
  let depth = 0;
  for (let k = 0; k < parts.length; k++) {
    const p = parts[k];
    if (p.startsWith('<')) {
      if (BLOCKED.test(p)) depth += p.startsWith('</') ? -1 : 1;
      if (depth < 0) depth = 0;
      continue;
    }
    if (depth > 0 || !p.trim()) continue;
    const m = p.match(re);
    if (m) {
      parts[k] = p.replace(re, '<a href="' + url + '">' + m[0] + '</a>');
      return { html: parts.join(''), ok: true, matched: m[0] };
    }
  }
  return { html: source, ok: false, matched: null };
}

const firstH2 = original.search(/<h2\b/i);
const lastH2 = original.search(/<h2\b(?![\s\S]*<h2\b)/i);
let intro = firstH2 > 0 ? original.slice(0, firstH2) : '';
let body  = firstH2 > 0 ? (lastH2 > firstH2 ? original.slice(firstH2, lastH2) : original.slice(firstH2)) : original;
let concl = (firstH2 > 0 && lastH2 > firstH2) ? original.slice(lastH2) : '';

const get = { intro: () => intro, body: () => body, conclusion: () => concl };
const set = (n, v) => { if (n === 'intro') intro = v; else if (n === 'body') body = v; else concl = v; };

const usedUrls = new Set(originalHrefs);
const usedAnchors = new Set();
const applied = [];
const rejected = [];
let introCount = 0;

for (const l of linksAdded) {
  if (applied.length >= 7) break;
  const url = String(l.url || '').trim().replace(/\/+$/, '');
  const anchor = String(l.anchor_text || '').trim();
  const key = anchor.toLowerCase();
  if (!url || url === selfUrl) { rejected.push({ url, why: 'self/prazan' }); continue; }
  if (!whitelist.has(url)) { rejected.push({ url, why: 'van liste kandidata' }); continue; }
  if (usedUrls.has(url)) { rejected.push({ url, why: 'duplikat URL' }); continue; }
  if (usedAnchors.has(key)) { rejected.push({ url, anchor, why: 'duplikat anchora' }); continue; }

  const want = ['intro', 'body', 'conclusion'].includes(l.placement) ? l.placement : 'body';
  const order = [want, ...['body', 'conclusion', 'intro'].filter(r => r !== want)];
  let done = false;
  for (const region of order) {
    if (region === 'intro' && introCount >= 2) continue;
    const src = get[region]();
    if (!src) continue;
    const r = insertLink(src, anchor, url);
    if (r.ok) {
      set(region, r.html);
      usedUrls.add(url); usedAnchors.add(key);
      if (region === 'intro') introCount++;
      applied.push({ url, anchor_text: r.matched, placement: region, reason: l.reason || '' });
      done = true;
      break;
    }
  }
  if (!done) rejected.push({ url, anchor, why: 'anchor nije nadjen u tekstu van headinga i van postojecih linkova' });
}

const rebuilt = intro + body + concl;
const structureOk =
  count(rebuilt, /<h2\b/gi) === count(original, /<h2\b/gi) &&
  count(rebuilt, /<h3\b/gi) === count(original, /<h3\b/gi) &&
  count(rebuilt, /<li\b/gi) === count(original, /<li\b/gi) &&
  count(rebuilt, /<tr\b/gi) === count(original, /<tr\b/gi) &&
  rebuilt.length >= original.length;

return {
  json: {
    output: { ...seo, content: structureOk ? rebuilt : original },
    interlinkMode: structureOk ? 'fallback' : 'original',
    interlinks: structureOk ? applied : [],
    interlinkCount: structureOk ? applied.length : 0,
    interlinkSkippedReason: skippedReason,
    interlinkFailures: failures,
    interlinksRejected: rejected
  }
};

